SELECT GSoffered
FROM schools
WHERE Longitude = (SELECT MAX(CASE WHEN Longitude < 0 THEN -Longitude ELSE Longitude END) FROM schools);

SELECT Text
FROM comments
WHERE UserId = (SELECT Id FROM users WHERE DisplayName = 'A Lion');

SELECT SUM(CASE WHEN publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero
JOIN publisher ON superhero.publisher_id = publisher.id;
